base=load(P/'baseline-v1.json');MAIN=R/base['main']['path'];assert sha(MAIN)==base['main']['sha256'];sp=importlib.util.spec_from_file_location('h',R/'evaluations/T-0781/implementation/stage_exact_two_settled_package_v2.py');h=importlib.util.module_from_spec(sp);sp.loader.exec_module(h);c=h.conn(MAIN);assert h.state(c)==base['state']
