save('single-original-metadata-input-v1.json',{'record_revision':r['id'],'source_revision':source['id'],'citation':'C-0446','image_id':'C0043834_00110','path':str(path.relative_to(R)),'sha256':digest,'bytes':path.stat().st_size,'dimensions':dimensions,'format':fmt,'EXIF_orientation':orientation,'canonical_record_asset':asset[0],'canonical_asset':meta,'provenance_text':'Frozen accepted C0446 citation and exact native record/source/origin metadata; no new access or provider-version assertion','provider_version':'unknown unless exact existing source metadata specifies otherwise','reading_scope':'Brita P0337 complete ownrow including correct headers/dittos/blanks/margins and necessary attribution ONLY; no other family ownfield extraction','crop_status':'No derivative generated; full exact original is supplied. Row/header coordinates to be determined independently by SOURCE readers; no invented row-location metadata.','original_images':1,'new_downloads':0,'mechanical_image_inspection':'Only file hash/header dimensions/EXIF metadata; no content interpretation'})
